RTSAVE7  DS    18F
*
* COBUPSI -- set the eight switches from the EXEC PARM.
*
* PARM='/UPSI(10100000)' is the form IBM's later compilers
* take, and the one the runtime looks for: the literal UPSI
* anywhere in the parameter text, then the next eight 0 or 1
* characters, leftmost being UPSI-0. Anything else leaves all
* eight off, which is the documented default.
COBUPSI  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE6+4
         LA    11,RTSAVE6
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(parameter text)
         LA    2,0(0,2)            drop the end-of-list bit
         XC    RTUPSI,RTUPSI       all off unless the PARM says otherwi
         LH    3,0(0,2)            its length
         LA    4,2(0,2)            the text itself
         CH    3,UPSIMIN           room for UPSI and eight digits?
         BL    UPSX
         SH    3,UPSIMIN
         LA    3,1(3)              positions worth trying
UPS10    CLC   0(4,4),UPSITAG
         BE    UPS15
         LA    4,1(4)
         BCT   3,UPS10
         B     UPSX                no UPSI in the parameter
UPS15    LA    4,4(4)              past the tag
         CLI   0(4),C'0'
         BE    UPS20
         CLI   0(4),C'1'
         BE    UPS20
         LA    4,1(4)              skip a ( or an =
UPS20    SR    5,5                 the byte being built
         LA    6,8                 eight of them
UPS30    SLL   5,1
         CLI   0(4),C'1'
         BNE   UPS40
         LA    5,1(5)
UPS40    LA    4,1(4)
         BCT   6,UPS30
         ST    5,RTUPSI            the byte, for the caller to store
UPSX     L     13,4(13)
         L     15,RTUPSI           the byte, while R12 is still ours
         ST    15,16(13)           into the save area's R15 slot
         LM    14,12,12(13)
         BR    14
*
* COBACC -- one transfer from SYSIN into the caller's item.
*
* General rule 2 on II-53 leaves the size of a transfer to the
* implementor: here it is one 80-column record. The buffer is
* blanked first, so a receiver wider than a card is padded and
* a read past the last card returns spaces rather than the
* card before it.
*
* Parameter list: A(item), A(halfword length).
COBACC   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE5+4
         LA    11,RTSAVE5
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(item)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)            length still to fill
COBA005  LTR   4,4
         BNP   COBA040             filled
         MVI   ACCBUF,C' '
         MVC   ACCBUF+1(255),ACCBUF  blank the buffer
         CLI   ACCEOFF,X'01'       already at end of file?
         BE    COBA020
         CLI   ACCOPEN,X'01'       already open?
         BE    COBA010
         OPEN  (ACCDCB,INPUT)
         MVI   ACCOPEN,X'01'
COBA010  LA    1,COBA030
         STCM  1,7,ACCDCB+33       into DCBEODAD
         GET   ACCDCB,ACCBUF       one card
         B     COBA020
COBA030  MVI   ACCEOFF,X'01'       end of file: the buffer stays blank
COBA020  LR    5,4
         CH    5,ACCCARD
         BNH   COBA035
         LH    5,ACCCARD           one card's worth
COBA035  BCTR  5,0                 EX wants length-1
         EX    5,COBAMVC
         LA    2,1(5,2)            past what was stored
         LA    5,1(5)
         SR    4,5
         B     COBA005
COBA040  L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
COBAMVC  MVC   0(0,2),ACCBUF       patched by EX
ACCCARD  DC    H'80'               a card
*
* COBTERM -- close SYSOUT if COBDISP ever opened it.
*
COBTERM  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE2+4
         LA    11,RTSAVE2
         ST    11,8(13)
         LR    13,11
         CLI   ACCOPEN,X'01'
         BNE   COBT005
         CLOSE (ACCDCB)
         MVI   ACCOPEN,X'00'
COBT005  CLI   RTOPEN,X'01'
         BNE   COBT010
         CLOSE (RTDCB)
         MVI   RTOPEN,X'00'
COBT010  L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
*
* COBDATE -- fill an 8-byte field with MM/DD/YY.
*   R1 -> the field.  TIME DEC hands back the date as packed
*   00YYDDDF, which is Julian, so the day of year has to be
*   walked into a month and a day.
*
COBDATE  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE4+4
         LA    11,RTSAVE4
         ST    11,8(13)
         LR    13,11
         LR    2,1                 the field, before TIME takes R1
         TIME  DEC                 R0 = HHMMSSth, R1 = 00YYDDDF
         ST    1,DTPACK
         UNPK  DTZONE(7),DTPACK(4)  '00YYDDD'
         OI    DTZONE+6,X'F0'
         PACK  DTDW(8),DTZONE+4(3)
         CVB   3,DTDW              day of the year
         PACK  DTDW(8),DTZONE+2(2)
         CVB   4,DTDW              the year
         N     4,DTF3              zero if a leap year -- 1901-2099, so
*                             mod 4 is the whole rule
         LA    5,1                 month
         LA    6,DTMON
DT010    SR    7,7
         IC    7,0(0,6)            days in this month
         CH    5,DTH2              February?
         BNE   DT020
         LTR   4,4
         BNZ   DT020
         LA    7,1(0,7)            29 this year
DT020    CR    3,7
         BNH   DT030               the day falls in this month
         SR    3,7
         LA    5,1(0,5)
         LA    6,1(0,6)
         B     DT010
DT030    CVD   5,DTDW
         UNPK  0(2,2),DTDW+6(2)    MM
         OI    1(2),X'F0'
         MVI   2(2),C'/'
         CVD   3,DTDW
         UNPK  3(2,2),DTDW+6(2)    DD
         OI    4(2),X'F0'
         MVI   5(2),C'/'
         MVC   6(2,2),DTZONE+2     YY, already zoned
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
DTMON    DC    AL1(31,28,31,30,31,30,31,31,30,31,30,31)
DTF3     DC    F'3'
DTH2     DC    H'2'
DTPACK   DS    F
DTZONE   DS    CL8
DTDW     DS    D
RTSAVE4  DS    18F
*
* COBWRL -- advance the paper and write one report line.
*   R1 -> A(dcb), A(current line), A(target line), A(buffer)
*
COBWRL   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE3+4
         LA    11,RTSAVE3
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(dcb)
         L     3,4(0,1)            A(current line)
         L     4,8(0,1)            A(target line)
         L     5,12(0,1)           A(buffer)
         LH    6,0(0,3)
         LH    7,0(0,4)
COBW010  LA    8,1(0,6)
         CR    8,7                 already at the line before the targe
         BNL   COBW020
         PUT   (2),RTBLNK          skip a line
         LA    6,1(0,6)
         B     COBW010
COBW020  PUT   (2),(5)
         STH   7,0(0,3)            current line = target
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
RTBLNK   DC    CL133' '            a blank line, ASA single space
RTSAVE3  DS    18F
RTOPEN   DC    X'00'
RTMAX    DC    H'120'
RTLINE   DC    CL121' '            ASA byte + 120 columns
RTSAVE1  DS    18F
RTSAVE2  DS    18F
RTSAVE5  DS    18F
RTSAVE6  DS    18F
RTUPSI   DS    F
UPSITAG  DC    C'UPSI'
UPSIMIN  DC    H'12'               UPSI, a bracket, eight digits
ACCOPEN  DC    X'00'
ACCEOFF  DC    X'00'
ACCBUF   DC    CL256' '            one card from SYSIN, blank padded
ACCMAX   DC    H'256'
ACCDCB   DCB   DDNAME=SYSIN,DSORG=PS,MACRF=(GM),                       X
               EODAD=0
RTDCB    DCB   DDNAME=SYSOUT,DSORG=PS,MACRF=(PM),RECFM=FBA,            X
               LRECL=121,BLKSIZE=121
*
* COBSTR -- STRING. R1 -> AL4(receiver), AL2(len), AL2(n),
*   AL4(pointer cell or 0); then per item AL4(addr), AL2(len),
*   AL2(delimiter len, 0 for SIZE), AL4(delimiter addr).
* Each item goes byte by byte until its delimiter matches or
* it runs out; the receiver filling up is the overflow, and
* a pointer outside 1..len is overflow with nothing moved.
* R15 = 0 done, 1 overflow. Other bytes of the receiver are
* not touched, which is the rule: STRING does not space-fill.
COBSTR   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE8+4
         LA    11,RTSAVE8
         ST    11,8(13)
         LR    13,11
         LR    2,1                 the block
         L     3,0(2)              receiver
         LH    5,4(2)              its length
         LH    7,6(2)              items
         L     4,8(2)              pointer cell
         LTR   4,4
         BZ    STR010              none: start at 1
         L     4,0(4)
         B     STR020
STR010   LA    4,1
STR020   BCTR  4,0                 position, from 0
         LTR   4,4
         BM    STRBAD              pointer below 1
         CR    4,5
         BNL   STRBAD              pointer past the end
         LA    6,12(2)             the first item
STR100   LTR   7,7
         BZ    STRDONE             all items sent
         L     8,0(6)              item
         LH    9,4(6)              its length
         LH    11,6(6)             delimiter length
         L     10,8(6)             delimiter
STR110   LTR   9,9
         BZ    STR190              item exhausted
         LTR   11,11
         BZ    STR120              SIZE: no delimiter to look for
         CR    9,11
         BL    STR120              too few left to hold the delimiter
         LR    15,11
         BCTR  15,0
         EX    15,STRCLC           delimiter here?
         BE    STR190              yes: the item ends
STR120   CR    4,5
         BNL   STROVF              receiver full
         LA    15,0(3,4)
         MVC   0(1,15),0(8)        one byte
         LA    8,1(8)
         BCTR  9,0
         LA    4,1(4)
         B     STR110
STR190   LA    6,12(6)             next item
         BCTR  7,0
         B     STR100
STRDONE  SR    15,15
         B     STRRET
STROVF   LA    15,1                overflow
STRRET   L     14,8(2)             pointer cell
         LTR   14,14
         BZ    STRX
         LA    4,1(4)              back to counting from 1
         ST    4,0(14)
         B     STRX
STRBAD   LA    15,1                pointer out of range: overflow, noth
STRX     L     13,4(13)
         ST    15,16(13)           R15 survives the LM through its own
         LM    14,12,12(13)
         BR    14
STRCLC   CLC   0(0,8),0(10)        executed with the delimiter length
RTSAVE8  DS    18F
*
* COBUNS -- UNSTRING. R1 -> AL4(sender), AL2(len), AL2(nd),
*   AL4(pointer cell or 0), AL4(tally cell or 0), AL2(nr),
*   AL2(0), AL4(0); then nd delimiters AL4(addr), AL2(len),
*   AL2(ALL); then nr receivers AL4(addr), AL2(len),
*   AL2(DELIMITER IN len), AL4(DELIMITER IN or 0),
*   AL4(COUNT IN cell or 0).
* For each receiver the sender is scanned from the position
* for the first place any delimiter matches, delimiters tried
* in order; the bytes before it go to the receiver, left
* justified and space filled. No delimiters means a receiver
* takes its own length. Bytes left when the receivers are
* used up are the overflow. R15 = 0 done, 1 overflow.
COBUNS   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE9+4
         LA    11,RTSAVE9
         ST    11,8(13)
         LR    13,11
         LR    2,1                 the block
         L     3,0(2)              sender
         LH    5,4(2)              its length
         LH    10,6(2)             delimiters
         L     4,8(2)              pointer cell
         LTR   4,4
         BZ    UNS010
         L     4,0(4)
         B     UNS020
UNS010   LA    4,1
UNS020   BCTR  4,0                 position, from 0
         LTR   4,4
         BM    UNSBAD
         CR    4,5
         BNL   UNSBAD              pointer past the end
         LH    7,16(2)             receivers
         LR    6,10
         SLL   6,3                 eight bytes per delimiter
         LA    6,24(6,2)           the first receiver
UNS100   LTR   7,7
         BZ    UNSEND              receivers used up
         CR    4,5
         BNL   UNSEND              sender used up: the rest stay as the
         LR    8,4                 scan from the position
         SR    9,9                 no delimiter matched yet
         LTR   10,10
         BZ    UNS140              no delimiters: take the receiver's l
UNS110   CR    8,5
         BNL   UNS170              end of the sender, no delimiter
         LA    9,24(2)             the first delimiter
         LR    0,10
UNS120   L     14,0(9)             delimiter
         LH    15,4(9)             its length
         LR    1,5
         SR    1,8                 bytes left
         CR    1,15
         BL    UNS130              not enough left for this one
         LA    1,0(3,8)
         BCTR  15,0
         EX    15,UNSCLC           matches here?
         BE    UNS170              yes, R9 says which
UNS130   LA    9,8(9)              next delimiter
         BCT   0,UNS120
         SR    9,9                 none matched at this byte
         LA    8,1(8)
         B     UNS110
UNS140   LH    1,4(6)              receiver length
         LA    8,0(4,1)            position plus that
         CR    8,5
         BNH   UNS170
         LR    8,5                 but no further than the end
UNS170   L     14,0(6)             receiver
         LH    15,4(6)             its length
         MVI   0(14),C' '
         LR    11,15
         BCTR  11,0
         LTR   11,11
         BZ    UNS172              a one-byte receiver is filled
         BCTR  11,0
         EX    11,UNSPAD           space fill
UNS172   LR    1,8
         SR    1,4                 bytes to move
         L     11,12(6)            COUNT IN cell
         LTR   11,11
         BZ    UNS174
         ST    1,0(11)             the count, before truncation
UNS174   CR    1,15
         BNH   UNS176
         LR    1,15                truncated on the right
UNS176   LTR   1,1
         BZ    UNS180              nothing to move
         BCTR  1,0
         LA    15,0(3,4)
         EX    1,UNSMVC            the bytes
UNS180   L     14,8(6)             DELIMITER IN
         LTR   14,14
         BZ    UNS186
         LH    15,6(6)             its length
         MVI   0(14),C' '
         LR    11,15
         BCTR  11,0
         LTR   11,11
         BZ    UNS182
         BCTR  11,0
         EX    11,UNSPAD           space fill
UNS182   LTR   9,9
         BZ    UNS186              no delimiter: spaces
         LH    1,4(9)              delimiter length
         CR    1,15
         BNH   UNS184
         LR    1,15
UNS184   BCTR  1,0
         L     15,0(9)
         EX    1,UNSMVC            the delimiter
UNS186   L     14,12(2)            TALLYING cell
         LTR   14,14
         BZ    UNS188
         L     15,0(14)
         LA    15,1(15)            one more receiver acted on
         ST    15,0(14)
UNS188   LTR   9,9
         BZ    UNS196              no delimiter: position is where the
         LH    1,4(9)              delimiter length
         LA    4,0(1,8)            past the delimiter
         LH    0,6(9)              ALL?
         LTR   0,0
         BZ    UNS198
UNS190   LR    0,5
         SR    0,4                 bytes left
         CR    0,1
         BL    UNS198              not enough for another copy
         LA    15,0(3,4)
         L     14,0(9)
         LR    11,1
         BCTR  11,0
         EX    11,UNSCLC2          another copy of the delimiter?
         BNE   UNS198
         LA    4,0(1,4)            skip it too
         B     UNS190
UNS196   LR    4,8
UNS198   LA    6,16(6)             next receiver
         BCTR  7,0
         B     UNS100
UNSEND   SR    15,15
         CR    4,5
         BNL   UNS200
         LA    15,1                bytes left over: overflow
UNS200   L     14,8(2)             pointer cell
         LTR   14,14
         BZ    UNSX
         LA    4,1(4)
         ST    4,0(14)
         B     UNSX
UNSBAD   LA    15,1                pointer out of range: overflow, noth
UNSX     L     13,4(13)
         ST    15,16(13)           R15 survives the LM through its own
         LM    14,12,12(13)
         BR    14
UNSCLC   CLC   0(0,1),0(14)        executed with the delimiter length
UNSCLC2  CLC   0(0,15),0(14)
UNSMVC   MVC   0(0,14),0(15)       executed with the byte count
UNSPAD   MVC   1(0,14),0(14)       executed: propagate the space
RTSAVE9  DS    18F
*
* COBWTO -- DISPLAY UPON CONSOLE. R1 -> A(text), A(halfword length).
* The text goes into a WTO list whose length halfword is set
* from the parameter; MVS caps a line at what it will show.
COBWTO   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE10+4
         LA    11,RTSAVE10
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(text)
         L     3,4(0,1)            A(length)
         LH    4,0(0,3)
         CH    4,WTOMAX
         BNH   WTO010
         LH    4,WTOMAX
WTO010   MVI   WTOTXT,C' '
         MVC   WTOTXT+1(119),WTOTXT
         LTR   4,4
         BNP   WTO020
         BCTR  4,0
         EX    4,WTOMVC
         LA    4,1(4)
WTO020   LA    4,4(4)              plus the header
         STH   4,WTOLST
         WTO   MF=(E,WTOLST)
         L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
WTOMVC   MVC   WTOTXT(0),0(2)      executed
WTOMAX   DC    H'120'
WTOLST   DC    AL2(124),AL2(0)     length, MCS flags
WTOTXT   DC    CL120' '
RTSAVE10 DS    18F
*
* COBWTOR -- ACCEPT FROM CONSOLE. R1 -> A(item), A(halfword length).
* A WTOR asks the operator, the task waits on its ECB, and the
* reply is moved to the item space padded. One line only.
COBWTOR  STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE11+4
         LA    11,RTSAVE11
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            A(item)
         L     3,4(0,1)            A(length)
