         LTR   4,4
         BNP   WTOR20
         CH    4,WTORMAX
         BNH   WTOR10
         LH    4,WTORMAX
WTOR10   BCTR  4,0
         EX    4,WTORMVC
WTOR20   L     13,4(13)
         LM    14,12,12(13)
         SR    15,15
         BR    14
WTORMVC  MVC   0(0,2),WTORRPL      executed
WTORMAX  DC    H'120'
WTORECB  DC    F'0'
WTORRPL  DC    CL120' '
RTSAVE11 DS    18F
*
* COBADT -- ACCEPT FROM DATE, DAY or TIME. R1 -> A(area), A(halfword
* kind: 1 DATE, 2 DAY, 3 TIME). Writes YYMMDD, YYDDD or HHMMSSth as
* zoned digits into the area. DATE borrows COBDATE's month walk.
COBADT   STM   14,12,12(13)
         BALR  12,0
         USING *,12
         ST    13,RTSAVE12+4
         LA    11,RTSAVE12
         ST    11,8(13)
         LR    13,11
         L     2,0(0,1)            the area
         L     3,4(0,1)
         LH    3,0(0,3)            the kind
         CH    3,ADTH3
         BE    ADT300              TIME
